from datetime import datetime, timezone
from sqlalchemy import (
    Column, Integer, String, Float, Boolean, DateTime, ForeignKey, Index, Text, JSON
)
from sqlalchemy.orm import relationship
from backend.app.database.session import Base

# Permanent mandatory advisory notice
DEFAULT_SAFETY_DISCLAIMER = (
    "ENGINEER REVIEW REQUIRED: Restoration switching recommendations generated by FAULTTRACE AI "
    "are strictly advisory. Physical verification of lockout/tagout (LOTO) protocols and human dispatcher "
    "authorization are mandatory prior to any switch operation."
)


class Incident(Base):
    __tablename__ = "incidents"

    id = Column(Integer, primary_key=True, index=True)
    scenario_id = Column(String(50), nullable=False, index=True)  # Scenario-ID based grouping for train/val/test integrity
    feeder_id = Column(Integer, ForeignKey("feeders.id", ondelete="CASCADE"), nullable=False, index=True)
    root_cause_section_id = Column(Integer, ForeignKey("feeder_sections.id", ondelete="SET NULL"), nullable=True, index=True)
    actual_fault_section_id = Column(Integer, ForeignKey("feeder_sections.id", ondelete="SET NULL"), nullable=True, index=True)  # Ground-truth simulated fault for evaluation
    start_time = Column(DateTime(timezone=True), nullable=False, index=True)
    end_time = Column(DateTime(timezone=True), nullable=True)
    status = Column(String(30), nullable=False, default="INVESTIGATING", index=True)  # INVESTIGATING, CONFIRMED, RESTORING, RESOLVED
    fault_type = Column(String(50), nullable=False, default="LINE_TO_GROUND")  # LINE_TO_GROUND, LINE_TO_LINE, DOUBLE_LINE_GROUND, THREE_PHASE, VEGETATION_CONTACT, CABLE_PUNCTURE
    estimated_customers_affected = Column(Integer, nullable=False, default=0)
    correlation_window_start = Column(DateTime(timezone=True), nullable=True)
    correlation_window_end = Column(DateTime(timezone=True), nullable=True)
    description = Column(Text, nullable=True)
    created_at = Column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False)
    updated_at = Column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), onupdate=lambda: datetime.now(timezone.utc), nullable=False)

    # Relationships
    feeder = relationship("Feeder", back_populates="incidents")
    root_cause_section = relationship("FeederSection", foreign_keys=[root_cause_section_id])
    actual_fault_section = relationship("FeederSection", foreign_keys=[actual_fault_section_id])
    outage_events = relationship("OutageEvent", back_populates="incident")
    candidates = relationship("FaultCandidate", back_populates="incident", cascade="all, delete-orphan")
    predictions = relationship("ModelPrediction", back_populates="incident", cascade="all, delete-orphan")
    restoration_steps = relationship("RestorationPriority", back_populates="incident", cascade="all, delete-orphan")

    __table_args__ = (
        Index("idx_incident_scenario_feeder", "scenario_id", "feeder_id"),
    )


class FaultCandidate(Base):
    """
    Topology-consistent candidate fault sections identified via NetworkX graph reachability.
    Terminology constraint: 'topology-consistent candidates', never 'mathematical proof'.
    Score constraint: raw model output is a 'score', only calibrated output is a 'probability'.
    """
    __tablename__ = "fault_candidates"

    id = Column(Integer, primary_key=True, index=True)
    incident_id = Column(Integer, ForeignKey("incidents.id", ondelete="CASCADE"), nullable=False, index=True)
    section_id = Column(Integer, ForeignKey("feeder_sections.id", ondelete="CASCADE"), nullable=False, index=True)
    rank = Column(Integer, nullable=False, default=1)
    raw_score = Column(Float, nullable=False, default=0.0)  # Raw model output score from XGBoost
    calibrated_probability = Column(Float, nullable=False, default=0.0)  # Calibrated probability (Isotonic/Platt)
    is_topology_consistent = Column(Boolean, nullable=False, default=True)  # True if validated by graph reachability
    candidate_designation = Column(String(50), nullable=False, default="topology-consistent candidate")
    pruning_reason = Column(String(100), nullable=True)  # e.g., "Downstream of tripped recloser R-02"
    created_at = Column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False)

    # Relationships
    incident = relationship("Incident", back_populates="candidates")
    section = relationship("FeederSection")
    prediction = relationship("ModelPrediction", back_populates="candidate", uselist=False)

    __table_args__ = (
        Index("idx_candidate_incident_rank", "incident_id", "rank"),
    )


class ModelPrediction(Base):
    __tablename__ = "model_predictions"

    id = Column(Integer, primary_key=True, index=True)
    incident_id = Column(Integer, ForeignKey("incidents.id", ondelete="CASCADE"), nullable=False, index=True)
    candidate_id = Column(Integer, ForeignKey("fault_candidates.id", ondelete="CASCADE"), nullable=False, index=True)
    model_version = Column(String(50), nullable=False, default="xgboost-v1.0")
    raw_score = Column(Float, nullable=False)  # Raw uncalibrated score
    calibrated_probability = Column(Float, nullable=False)  # Calibrated probability
    calibration_method = Column(String(30), nullable=False, default="isotonic")  # isotonic, sigmoid/platt
    feature_snapshot = Column(JSON, nullable=True)  # Telemetry and graph feature vector
    shap_values = Column(JSON, nullable=True)  # Feature contribution attributions
    created_at = Column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False)

    # Relationships
    incident = relationship("Incident", back_populates="predictions")
    candidate = relationship("FaultCandidate", back_populates="prediction")


class RestorationPriority(Base):
    """
    Advisory restoration switching sequence with safety disclaimers.
    Never auto-executed: engineer review is mandatory.
    """
    __tablename__ = "restoration_priorities"

    id = Column(Integer, primary_key=True, index=True)
    incident_id = Column(Integer, ForeignKey("incidents.id", ondelete="CASCADE"), nullable=False, index=True)
    step_number = Column(Integer, nullable=False, default=1)
    action_type = Column(String(30), nullable=False)  # ISOLATE_SECTION, CLOSE_TIE_SWITCH, SHED_LOAD, ENERGIZE_BACKFEED
    switch_code = Column(String(50), nullable=False)
    target_section_id = Column(Integer, ForeignKey("feeder_sections.id", ondelete="SET NULL"), nullable=True)
    priority_score = Column(Float, nullable=False, default=1.0)
    critical_load_served = Column(Boolean, nullable=False, default=False)
    estimated_restored_kva = Column(Float, nullable=False, default=0.0)
    advisory_notes = Column(Text, nullable=True)
    safety_disclaimer = Column(Text, nullable=False, default=DEFAULT_SAFETY_DISCLAIMER)
    requires_engineer_approval = Column(Boolean, nullable=False, default=True)
    approval_status = Column(String(30), nullable=False, default="PENDING_REVIEW")  # PENDING_REVIEW, APPROVED, REJECTED
    created_at = Column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False)

    # Relationships
    incident = relationship("Incident", back_populates="restoration_steps")
    target_section = relationship("FeederSection")

    __table_args__ = (
        Index("idx_restoration_incident_step", "incident_id", "step_number"),
    )
